function SectionHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: React.ReactNode }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-[#789086]">{eyebrow}</p><h2 className="mt-2 font-display text-2xl font-semibold tracking-[-0.03em] text-[#18342e]">{title}</h2>{detail && <p className="mt-1 text-sm text-[#789086]">{detail}</p>}</div>{action}</div>;
}

function SimulatedBadge({ children = "Simulated" }: { children?: string }) { return <Badge variant="outline" className="border-[#cbe8d3] bg-[#effbf1] text-[10px] font-bold uppercase tracking-[0.14em] text-[#3d7e59]">{children}</Badge>; }
function AgentBadge({ label, tone = "green" }: { label: string; tone?: "green" | "purple" | "orange" }) { const colors = tone === "purple" ? "border-[#ddd2ff] bg-[#f6f2ff] text-[#7760ad]" : tone === "orange" ? "border-[#f3dfc4] bg-[#fff8ed] text-[#a66d27]" : "border-[#cbe8d3] bg-[#effbf1] text-[#3d7e59]"; return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.13em] ${colors}`}><Sparkles className="h-3 w-3" />{label}</span>; }
function IconBubble({ children, tone = "green" }: { children: React.ReactNode; tone?: "green" | "purple" | "orange" | "blue" }) { const classes = { green: "bg-[#dff6e6] text-[#3d8c5d]", purple: "bg-[#efe8ff] text-[#846bc0]", orange: "bg-[#fff0d8] text-[#ad7734]", blue: "bg-[#e4efff] text-[#4f80bc]" }; return <div className={`grid h-10 w-10 shrink-0 place-items-center rounded-2xl ${classes[tone]}`}>{children}</div>; }
function EmptyState({ title, detail }: { title: string; detail: string }) { return <div className="rounded-2xl border border-dashed border-[#d5e6da] bg-[#fbfdfb] p-8 text-center"><CircleAlert className="mx-auto h-7 w-7 text-[#a4b9ad]" /><p className="mt-3 font-semibold text-[#36574a]">{title}</p><p className="mt-1 text-sm text-[#80948a]">{detail}</p></div>; }

function usePlatformData() {
  const { user, isAuthenticated } = useAuth();
  const dashboardQuery = trpc.dashboard.snapshot.useQuery(undefined, { enabled: isAuthenticated });
  const contactsQuery = trpc.dashboard.contacts.useQuery(undefined, { enabled: isAuthenticated });
  const billsQuery = trpc.bills.snapshot.useQuery(undefined, { enabled: isAuthenticated });
  const controlsQuery = trpc.controls.get.useQuery(undefined, { enabled: isAuthenticated });
  const auditQuery = trpc.dashboard.audit.useQuery(undefined, { enabled: isAuthenticated });
  const notificationsQuery = trpc.dashboard.notifications.useQuery(undefined, { enabled: isAuthenticated });
  return {
    user,
    isAuthenticated,
    profile: dashboardQuery.data?.profile ?? demoProfile,
    transactions: dashboardQuery.data?.transactions ?? demoTransactions,
    contacts: contactsQuery.data?.length ? contactsQuery.data : demoContacts,
    bills: billsQuery.data?.bills?.length ? billsQuery.data.bills : demoBills,
    plans: billsQuery.data?.plans?.length ? billsQuery.data.plans : demoPlans,
    escalations: billsQuery.data?.escalations ?? [],
    controls: controlsQuery.data ?? { autoSwitchEnabled: 0, maxMonthlySavingsCents: 0, maxPriceIncreaseCents: 0, notifyPush: 1, notifyEmail: 1, notifySms: 1 },
    audit: auditQuery.data?.length ? auditQuery.data : demoAudit,
    notifications: notificationsQuery.data ?? [],
    refresh: () => { dashboardQuery.refetch(); contactsQuery.refetch(); billsQuery.refetch(); controlsQuery.refetch(); auditQuery.refetch(); notificationsQuery.refetch(); },
  };
}

