function Metric({ label, value, delta }: { label: string; value: string; delta: string }) { return <div className="rounded-2xl border border-[#416b5b] bg-[#21473c]/70 p-3"><p className="text-[10px] uppercase tracking-[0.14em] text-[#9fbeaf]">{label}</p><p className="mt-1 text-sm font-semibold text-white">{value}</p><p className="mt-1 text-[10px] text-[#9ae7b5]">{delta}</p></div>; }
function ActionCard({ icon, title, detail, tone, onClick }: { icon: React.ReactNode; title: string; detail: string; tone: "green" | "purple" | "orange" | "blue"; onClick: () => void }) { return <button onClick={onClick} className="group flex items-center gap-4 rounded-2xl border border-[#e5eee8] bg-white p-4 text-left shadow-sm transition duration-200 hover:-translate-y-0.5 hover:border-[#cce5d3] hover:shadow-md"><IconBubble tone={tone}>{icon}</IconBubble><span className="min-w-0 flex-1"><span className="block font-semibold text-[#29473e]">{title}</span><span className="mt-1 block text-xs text-[#81948b]">{detail}</span></span><ChevronRight className="h-4 w-4 text-[#a6b9af] transition group-hover:translate-x-0.5 group-hover:text-[#4f9b68]" /></button>; }
function TransactionRow({ transaction }: { transaction: any }) { const incoming = transaction.direction === "in"; const icon = transaction.type === "merchant" ? <Building2 className="h-4 w-4" /> : transaction.type === "transit" ? <TrainFront className="h-4 w-4" /> : incoming ? <ArrowDownLeft className="h-4 w-4" /> : <ArrowUpRight className="h-4 w-4" />; return <div className="flex items-center gap-3 border-b border-[#edf3ee] py-3.5 last:border-b-0"><IconBubble tone={incoming ? "green" : transaction.type === "merchant" ? "orange" : "blue"}>{icon}</IconBubble><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#36574a]">{transaction.counterpartyName}</p><p className="mt-1 truncate text-xs text-[#8a9e94]">{transaction.note || "Simulated settlement"} · {new Date(transaction.createdAt).toLocaleDateString(undefined, { month: "short", day: "numeric" })}</p></div><div className="text-right"><p className={`text-sm font-semibold ${incoming ? "text-[#328156]" : "text-[#36574a]"}`}>{incoming ? "+" : "−"}{money(transaction.amountCents)}</p><p className="mt-1 text-[10px] uppercase tracking-wider text-[#9caf9f]">{transaction.status || "settled"}</p></div></div>; }
function OnboardingCard({ profile }: { profile: any }) { const steps = [{ label: "Phone + OTP", done: true }, { label: "Simulated KYC", done: true }, { label: "Bank link", done: true }, { label: "PIN + biometric", done: Boolean(profile.pinConfigured) }]; return <Card className="rounded-[1.75rem] border-[#e5eee8] bg-white shadow-sm"><CardContent className="p-6 sm:p-7"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><div className="flex items-center gap-2"><AgentBadge label="Profile status" tone="orange" /><SimulatedBadge /></div><h3 className="mt-3 font-display text-xl font-semibold text-[#24463b]">Your account is ready for everyday use.</h3><p className="mt-1 text-sm text-[#789086]">{profile.handle} · {profile.phone}</p></div><Button variant="outline" className="rounded-xl border-[#d9e9de] text-[#477d5b]">Edit profile <ChevronRight className="ml-2 h-4 w-4" /></Button></div><div className="mt-6 grid gap-3 sm:grid-cols-4">{steps.map(step => <div key={step.label} className="flex items-center gap-2 rounded-xl bg-[#f7faf7] p-3 text-xs font-medium text-[#6a8177]"><span className={`grid h-6 w-6 place-items-center rounded-full ${step.done ? "bg-[#dff6e6] text-[#3f9961]" : "bg-[#eef2ef] text-[#91a49a]"}`}>{step.done ? <Check className="h-3.5 w-3.5" /> : <span>4</span>}</span>{step.label}</div>)}</div></CardContent></Card>; }

function Payments() { const data = usePlatformData(); const [flow, setFlow] = useState<"send" | "merchant" | null>("send"); return <div><AppTopbar title="Payments" subtitle="P2P, merchant, QR, and contactless — one simulated rail." onYuna={() => setFlow("send")} /><div className="mx-auto max-w-[1440px] space-y-8 px-5 py-7 sm:px-8 lg:px-10"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-[#789086]">Payment core</p><h2 className="mt-2 font-display text-3xl font-semibold tracking-[-0.04em] text-[#18342e]">Move money with context.</h2></div><div className="flex gap-2"><Button onClick={() => setFlow("send")} className="rounded-xl bg-[#18342e] text-white hover:bg-[#2a594a]"><Send className="mr-2 h-4 w-4" /> Send</Button><Button onClick={() => setFlow("merchant")} variant="outline" className="rounded-xl border-[#d8e8dd] text-[#3d7e59]"><QrCode className="mr-2 h-4 w-4" /> Pay</Button></div></div><div className="grid gap-5 xl:grid-cols-[1.05fr_.95fr]"><Card className="rounded-[1.75rem] border-[#e5eee8] bg-white shadow-sm"><CardHeader className="flex flex-row items-start justify-between space-y-0 px-6 pb-2 pt-6"><div><CardTitle className="font-display text-xl text-[#24463b]">{flow === "merchant" ? "Merchant payment" : "Send money"}</CardTitle><p className="mt-1 text-sm text-[#789086]">{flow === "merchant" ? "Scan QR or simulate a contactless tap." : "Your recipient sees your real name before you confirm."}</p></div><SimulatedBadge>{flow === "merchant" ? "QR / NFC demo" : "Instant mock settlement"}</SimulatedBadge></CardHeader><CardContent className="px-6 pb-7">{flow === "merchant" ? <MerchantPaymentForm onSuccess={data.refresh} /> : <SendMoneyForm contacts={data.contacts} onSuccess={data.refresh} />}</CardContent></Card><Card className="rounded-[1.75rem] border-[#e5eee8] bg-[#f1f9f3] shadow-sm"><CardContent className="p-6"><div className="flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-[#6f8c7d]">Security by design</p><h3 className="mt-2 font-display text-2xl font-semibold text-[#24463b]">No silent approvals.</h3></div><ShieldCheck className="h-8 w-8 text-[#4b9c67]" /></div><div className="mt-6 space-y-3"><SecurityLine icon={<KeyRound className="h-4 w-4" />} title="PIN required every time" detail="No amount threshold bypasses confirmation." /><SecurityLine icon={<Fingerprint className="h-4 w-4" />} title="Biometric is layered" detail="Unlocks the client step; a PIN-equivalent event is still recorded server-side." /><SecurityLine icon={<Gauge className="h-4 w-4" />} title="$2,500 daily hard limit" detail="If exceeded, the transfer is blocked — no override." /></div><div className="mt-6 rounded-2xl border border-[#d5ebda] bg-white/80 p-4"><p className="text-xs font-semibold text-[#3b7252]">Your handle</p><p className="mt-1 font-display text-xl font-semibold text-[#24463b]">{data.profile.handle}</p><p className="mt-1 text-xs text-[#80968c]">UPI-style identity · tied to your demo profile</p></div></CardContent></Card></div><div><SectionHeading eyebrow="People" title="Saved contacts" detail="Full-name matching keeps voice payments unambiguous." /><div className="grid gap-3 sm:grid-cols-3">{data.contacts.map((contact: any) => <button key={contact.id} onClick={() => setFlow("send")} className="flex items-center gap-3 rounded-2xl border border-[#e5eee8] bg-white p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="grid h-10 w-10 place-items-center rounded-2xl text-sm font-semibold text-[#315f4c]" style={{ background: contact.color || "#a7e9d1" }}>{initials(contact.displayName)}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#36574a]">{contact.displayName}</p><p className="mt-1 truncate text-xs text-[#81948b]">{contact.handle}</p></div><ChevronRight className="h-4 w-4 text-[#a7b8ad]" /></button>)}</div></div></div></div>; }
function SecurityLine({ icon, title, detail }: { icon: React.ReactNode; title: string; detail: string }) { return <div className="flex gap-3 rounded-2xl border border-[#d9ecde] bg-white/70 p-3"><IconBubble>{icon}</IconBubble><div><p className="text-sm font-semibold text-[#36574a]">{title}</p><p className="mt-1 text-xs leading-5 text-[#81948b]">{detail}</p></div></div>; }

function SendMoneyForm({ contacts, onSuccess }: { contacts: any[]; onSuccess: () => void }) { const sendMutation = trpc.payments.send.useMutation({ onSuccess: () => { toast.success("Payment settled in demo mode"); onSuccess(); setStep(1); }, onError: error => toast.error(error.message) }); const [step, setStep] = useState(1); const [recipient, setRecipient] = useState(contacts[0]?.displayName || "Ali Rahman"); const [amount, setAmount] = useState("100"); const [note, setNote] = useState("Dinner"); const [authMethod, setAuthMethod] = useState<"pin" | "biometric">("biometric"); const selected = contacts.find(contact => contact.displayName === recipient) || contacts[0]; const amountCents = Math.round(Number(amount || 0) * 100); return <div className="pt-4"><div className="mb-7 flex items-center gap-2">{["Recipient", "Amount", "Review", "Confirm"].map((label, index) => <div key={label} className="flex flex-1 items-center gap-2"><div className={`grid h-7 w-7 place-items-center rounded-full text-xs font-bold ${step > index ? "bg-[#dff6e6] text-[#3d8c5d]" : step === index + 1 ? "bg-[#18342e] text-white" : "bg-[#eef3ef] text-[#8ba096]"}`}>{step > index + 1 ? <Check className="h-3.5 w-3.5" /> : index + 1}</div><span className={`hidden text-xs font-semibold sm:block ${step === index + 1 ? "text-[#36574a]" : "text-[#9aac9f]"}`}>{label}</span>{index < 3 && <div className="h-px flex-1 bg-[#e7efe9]" />}</div>)}</div>{step === 1 && <div className="space-y-5"><div><Label className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Recipient</Label><div className="mt-2 grid gap-2 sm:grid-cols-3">{contacts.map(contact => <button key={contact.id} onClick={() => setRecipient(contact.displayName)} className={`rounded-2xl border p-3 text-left transition ${recipient === contact.displayName ? "border-[#9fd8ae] bg-[#f0fbf2]" : "border-[#e5eee8] bg-white hover:border-[#cce4d3]"}`}><div className="flex items-center gap-2"><div className="grid h-8 w-8 place-items-center rounded-xl text-[10px] font-bold text-[#315f4c]" style={{ background: contact.color || "#a7e9d1" }}>{initials(contact.displayName)}</div><span className="truncate text-xs font-semibold text-[#36574a]">{contact.displayName}</span></div><p className="mt-2 truncate text-[10px] text-[#8da096]">{contact.handle}</p></button>)}</div><p className="mt-2 flex items-center gap-1.5 text-xs text-[#7e9489]"><BadgeCheck className="h-3.5 w-3.5 text-[#4c9e69]" />Full name matched · {selected?.displayName} is the recipient you selected.</p></div><Button onClick={() => setStep(2)} className="h-11 w-full rounded-xl bg-[#18342e] text-white hover:bg-[#2b5749]">Continue <ChevronRight className="ml-2 h-4 w-4" /></Button></div>}{step === 2 && <div className="space-y-5"><div><Label htmlFor="amount" className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Amount</Label><div className="relative mt-2"><span className="absolute left-4 top-1/2 -translate-y-1/2 font-display text-2xl text-[#789086]">$</span><Input id="amount" inputMode="decimal" value={amount} onChange={event => setAmount(event.target.value)} className="h-16 rounded-2xl border-[#dfece2] pl-10 font-display text-3xl font-semibold text-[#24463b] shadow-none focus-visible:ring-[#9fd8ae]" /></div></div><div><Label htmlFor="note" className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Note <span className="font-normal normal-case tracking-normal text-[#a0b0a7]">(optional)</span></Label><Input id="note" value={note} onChange={event => setNote(event.target.value)} placeholder="What's it for?" className="mt-2 h-11 rounded-xl border-[#dfece2] shadow-none" /></div><div className="flex items-center justify-between rounded-2xl bg-[#f7faf7] p-4"><div><p className="text-xs text-[#81958a]">Daily limit remaining</p><p className="mt-1 font-semibold text-[#36574a]">$2,500.00 <span className="text-xs font-normal text-[#5e9a72]">hard limit</span></p></div><Gauge className="h-5 w-5 text-[#599b6e]" /></div><div className="flex gap-2"><Button variant="outline" onClick={() => setStep(1)} className="h-11 rounded-xl border-[#dfece2]">Back</Button><Button onClick={() => setStep(3)} disabled={amountCents <= 0} className="h-11 flex-1 rounded-xl bg-[#18342e] text-white hover:bg-[#2b5749]">Review payment <ChevronRight className="ml-2 h-4 w-4" /></Button></div></div>}{step === 3 && <div className="space-y-5"><div className="rounded-2xl bg-[#f7faf7] p-5"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-[#dff6e6] text-sm font-semibold text-[#3d8c5d]">{initials(selected?.displayName)}</div><div><p className="text-sm font-semibold text-[#36574a]">{selected?.displayName}</p><p className="mt-1 text-xs text-[#81958a]">{selected?.handle}</p></div></div><div className="my-5 h-px bg-[#e1ece4]" /><div className="flex items-end justify-between"><div><p className="text-xs text-[#81958a]">Sending</p><p className="mt-1 font-display text-4xl font-semibold tracking-tight text-[#24463b]">{money(amountCents)}</p></div><div className="text-right"><p className="text-xs text-[#81958a]">Fee</p><p className="mt-1 font-semibold text-[#3d8c5d]">$0.00</p></div></div>{note && <p className="mt-4 rounded-xl bg-white px-3 py-2 text-xs text-[#6d8378]">“{note}”</p>}</div><div className="flex gap-2"><Button variant="outline" onClick={() => setStep(2)} className="h-11 rounded-xl border-[#dfece2]">Edit</Button><Button onClick={() => setStep(4)} className="h-11 flex-1 rounded-xl bg-[#18342e] text-white hover:bg-[#2b5749]">Confirm recipient <ChevronRight className="ml-2 h-4 w-4" /></Button></div></div>}{step === 4 && <div className="space-y-5"><div className="rounded-2xl border border-[#d5eadb] bg-[#f1faf3] p-5"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#d9f3df] text-[#4a9a65]"><LockKeyhole className="h-5 w-5" /></div><div><p className="font-semibold text-[#36574a]">Confirm with {authMethod === "biometric" ? "biometric" : "PIN"}</p><p className="mt-1 text-xs leading-5 text-[#789086]">{authMethod === "biometric" ? "Biometric unlock replaces PIN entry client-side." : "Your PIN is verified for this transaction."} Either way, the server records a PIN-equivalent auth event.</p></div></div></div><div className="grid grid-cols-2 gap-2"><button onClick={() => setAuthMethod("biometric")} className={`rounded-xl border p-3 text-left ${authMethod === "biometric" ? "border-[#9fd8ae] bg-[#f0fbf2]" : "border-[#e5eee8]"}`}><Fingerprint className="h-4 w-4 text-[#4d9b6d]" /><p className="mt-2 text-xs font-semibold text-[#36574a]">Biometric</p><p className="mt-1 text-[10px] text-[#8aa097]">Device unlock</p></button><button onClick={() => setAuthMethod("pin")} className={`rounded-xl border p-3 text-left ${authMethod === "pin" ? "border-[#9fd8ae] bg-[#f0fbf2]" : "border-[#e5eee8]"}`}><KeyRound className="h-4 w-4 text-[#4d9b6d]" /><p className="mt-2 text-xs font-semibold text-[#36574a]">PIN</p><p className="mt-1 text-[10px] text-[#8aa097]">6-digit demo PIN</p></button></div><div className="flex gap-2"><Button variant="outline" onClick={() => setStep(3)} className="h-11 rounded-xl border-[#dfece2]">Back</Button><Button onClick={() => sendMutation.mutate({ recipientName: selected?.displayName || recipient, recipientHandle: selected?.handle, amountCents, note, authMethod })} disabled={sendMutation.isPending} className="h-11 flex-1 rounded-xl bg-[#3c9d63] text-white hover:bg-[#328754]">{sendMutation.isPending ? "Settling…" : "Authorize & send"}<Send className="ml-2 h-4 w-4" /></Button></div></div>}</div>; }
function MerchantPaymentForm({ onSuccess }: { onSuccess: () => void }) { const mutation = trpc.payments.merchant.useMutation({ onSuccess: () => { toast.success("Merchant payment settled in demo mode"); onSuccess(); }, onError: error => toast.error(error.message) }); const [merchant, setMerchant] = useState("Bodega 17"); const [amount, setAmount] = useState("18.75"); const [method, setMethod] = useState<"pin" | "biometric">("biometric"); const [crossPlatform, setCrossPlatform] = useState(false); return <div className="space-y-5 pt-4"><div className="grid gap-3 sm:grid-cols-2"><button className="flex items-center gap-3 rounded-2xl border border-[#a9dcb6] bg-[#f0fbf2] p-4 text-left"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#dff6e6] text-[#3f9861]"><ScanLine className="h-5 w-5" /></div><div><p className="text-sm font-semibold text-[#36574a]">Scan QR</p><p className="mt-1 text-xs text-[#81948b]">Static or dynamic demo QR</p></div></button><button className="flex items-center gap-3 rounded-2xl border border-[#e5eee8] bg-white p-4 text-left"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#efe8ff] text-[#8167bd]"><CreditCard className="h-5 w-5" /></div><div><p className="text-sm font-semibold text-[#36574a]">Tap NFC</p><p className="mt-1 text-xs text-[#81948b]">Contactless demo reader</p></div></button></div><div className="rounded-2xl bg-[#f7faf7] p-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#fff0d8] text-[#ae7736]"><Building2 className="h-5 w-5" /></div><div className="flex-1"><p className="text-xs uppercase tracking-wider text-[#81958a]">Verified merchant</p><Input value={merchant} onChange={event => setMerchant(event.target.value)} className="mt-2 h-9 border-0 bg-transparent p-0 text-sm font-semibold text-[#36574a] shadow-none focus-visible:ring-0" /></div><BadgeCheck className="h-5 w-5 text-[#4e9b67]" /></div></div><div><Label className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Amount</Label><div className="relative mt-2"><span className="absolute left-4 top-1/2 -translate-y-1/2 font-display text-2xl text-[#789086]">$</span><Input value={amount} onChange={event => setAmount(event.target.value)} className="h-14 rounded-2xl border-[#dfece2] pl-10 font-display text-2xl font-semibold shadow-none" /></div></div><div className="flex items-center justify-between rounded-2xl border border-[#e6eee8] p-4"><div><p className="text-sm font-semibold text-[#36574a]">Cross-platform merchant?</p><p className="mt-1 text-xs text-[#81948b]">Adds the specified $0.01 demo fee.</p></div><Switch checked={crossPlatform} onCheckedChange={setCrossPlatform} /></div><div className="grid grid-cols-2 gap-2"><button onClick={() => setMethod("biometric")} className={`rounded-xl border p-3 text-left ${method === "biometric" ? "border-[#a9dcb6] bg-[#f0fbf2]" : "border-[#e5eee8]"}`}><Fingerprint className="h-4 w-4 text-[#4d9b6d]" /><p className="mt-2 text-xs font-semibold text-[#36574a]">Biometric</p></button><button onClick={() => setMethod("pin")} className={`rounded-xl border p-3 text-left ${method === "pin" ? "border-[#a9dcb6] bg-[#f0fbf2]" : "border-[#e5eee8]"}`}><KeyRound className="h-4 w-4 text-[#4d9b6d]" /><p className="mt-2 text-xs font-semibold text-[#36574a]">PIN</p></button></div><Button onClick={() => mutation.mutate({ merchantName: merchant, amountCents: Math.round(Number(amount) * 100), crossPlatform, authMethod: method })} disabled={mutation.isPending} className="h-11 w-full rounded-xl bg-[#18342e] text-white hover:bg-[#2b5749]">{mutation.isPending ? "Settling…" : "Authorize merchant payment"}<ShieldCheck className="ml-2 h-4 w-4" /></Button></div>; }

function Bills() { const data = usePlatformData(); const scan = trpc.bills.runScan.useMutation({ onSuccess: result => { toast.success(`${result.escalated} decision${result.escalated === 1 ? "" : "s"} escalated; nothing acted without a guardrail.`); data.refresh(); }, onError: error => toast.error(error.message) }); const decision = trpc.bills.decision.useMutation({ onSuccess: () => { toast.success("Decision recorded"); data.refresh(); } }); const [selected, setSelected] = useState(data.bills[0]?.id || 1); const activeBill = data.bills.find((bill: any) => bill.id === selected) || data.bills[0]; const activePlan = data.plans.find((plan: any) => plan.billId === activeBill?.id) || data.plans[0]; return <div><AppTopbar title="Bills & plans" subtitle="Bill Advisor compares cost and usage fit, then respects your guardrails." onYuna={() => toast("Ask Yuna to check a bill after signing in.")} /><div className="mx-auto max-w-[1440px] space-y-8 px-5 py-7 sm:px-8 lg:px-10"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-[#789086]">Bill-pay hub</p><h2 className="mt-2 font-display text-3xl font-semibold tracking-[-0.04em] text-[#18342e]">Know before you switch.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#789086]">The agent reviews the bill, market alternatives, and your actual usage pattern. Default behavior is always ask.</p></div><Button onClick={() => scan.mutate()} disabled={scan.isPending} className="h-11 rounded-xl bg-[#18342e] text-white hover:bg-[#2b5749]"><Sparkles className="mr-2 h-4 w-4" />{scan.isPending ? "Scanning…" : "Run monthly scan"}</Button></div><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="space-y-3">{data.bills.map((bill: any) => { const plan = data.plans.find((candidate: any) => candidate.billId === bill.id); return <button key={bill.id} onClick={() => setSelected(bill.id)} className={`w-full rounded-2xl border p-4 text-left transition ${selected === bill.id ? "border-[#9fd8ae] bg-[#f0fbf2] shadow-sm" : "border-[#e5eee8] bg-white hover:border-[#cbe5d2]"}`}><div className="flex items-start justify-between gap-3"><div className="flex items-center gap-3"><IconBubble tone={bill.category === "utility" ? "orange" : bill.category === "phone" ? "purple" : "blue"}>{bill.category === "utility" ? <Zap className="h-4 w-4" /> : bill.category === "phone" ? <Phone className="h-4 w-4" /> : <ShieldCheck className="h-4 w-4" />}</IconBubble><div><p className="text-sm font-semibold text-[#36574a]">{bill.provider}</p><p className="mt-1 text-xs text-[#81948b]">Due {bill.dueDate} · {bill.currentPlan}</p></div></div><div className="text-right"><p className="font-semibold text-[#36574a]">{money(bill.amountCents)}</p>{plan && <p className="mt-1 text-xs font-medium text-[#4d9867]">Save {money(plan.savingsCents)}</p>}</div></div><p className="mt-4 text-xs text-[#7f958a]">{bill.usageMetric}</p></button>; })}</div><Card className="rounded-[1.75rem] border-[#e5eee8] bg-white shadow-sm"><CardContent className="p-6 sm:p-7"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><AgentBadge label="Bill Advisor" tone="purple" /><SimulatedBadge /></div><h3 className="mt-4 font-display text-2xl font-semibold text-[#24463b]">Best fit for {activeBill?.provider}</h3><p className="mt-2 text-sm leading-6 text-[#789086]">Based on {activeBill?.usageMetric?.toLowerCase()}.</p></div><div className="rounded-2xl bg-[#f1eaff] px-4 py-3 text-right"><p className="text-[10px] font-bold uppercase tracking-wider text-[#8069b4]">Usage match</p><p className="mt-1 font-display text-2xl font-semibold text-[#6b54a3]">{activePlan?.usageFit || 0}%</p></div></div><div className="mt-7 grid gap-3 sm:grid-cols-3"><PlanMetric label="Current" value={money(activeBill?.amountCents || 0)} detail={activeBill?.currentPlan || "—"} /><PlanMetric label="Recommended" value={money(activePlan?.monthlyCents || 0)} detail={activePlan?.planName || "—"} /><PlanMetric label="Monthly savings" value={shortMoney(activePlan?.savingsCents || 0)} detail={activePlan?.contractLabel || "—"} tone="green" /></div><div className="mt-6 rounded-2xl border border-[#e8e0ff] bg-[#faf8ff] p-4"><div className="flex items-start gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#eee5ff] text-[#8169b8]"><CircleAlert className="h-4 w-4" /></div><div><p className="text-sm font-semibold text-[#5c4c8e]">Agent recommendation</p><p className="mt-1 text-xs leading-5 text-[#8173a7]">This option fits your pattern better than the current plan. It will never switch automatically until you enable a threshold in AI Controls.</p></div></div></div></CardContent></Card></div><EscalationPanel escalations={data.escalations} onDecision={id => decision.mutate({ escalationId: id, decision: "approved" })} /></div></div>; }
function PlanMetric({ label, value, detail, tone = "gray" }: { label: string; value: string; detail: string; tone?: "gray" | "green" }) { return <div className={`rounded-2xl p-4 ${tone === "green" ? "bg-[#effaf1]" : "bg-[#f7faf7]"}`}><p className="text-[10px] font-bold uppercase tracking-wider text-[#81968b]">{label}</p><p className={`mt-2 font-display text-2xl font-semibold ${tone === "green" ? "text-[#3d8c5d]" : "text-[#36574a]"}`}>{value}</p><p className="mt-1 truncate text-xs text-[#80958b]">{detail}</p></div>; }
function EscalationPanel({ escalations, onDecision }: { escalations: any[]; onDecision: (id: number) => void }) { return <Card className="rounded-[1.75rem] border-[#f1dfc7] bg-[#fffaf2] shadow-sm"><CardContent className="p-6"><div className="flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-[#aa7b40]">Escalations</p><h3 className="mt-2 font-display text-xl font-semibold text-[#5f4b32]">Your approval queue</h3></div><Clock3 className="h-5 w-5 text-[#c28f4e]" /></div>{escalations.length ? <div className="mt-5 space-y-3">{escalations.map(item => <div key={item.id} className="flex flex-col gap-3 rounded-2xl border border-[#f0e0c7] bg-white/75 p-4 sm:flex-row sm:items-center"><div className="flex-1"><p className="text-sm font-semibold text-[#5f4b32]">{item.prompt}</p><p className="mt-1 text-xs text-[#a28662]">Expires {new Date(item.expiresAt).toLocaleDateString()}</p></div><div className="flex gap-2"><Button onClick={() => onDecision(item.id)} className="h-9 rounded-lg bg-[#3d8c5d] px-3 text-xs text-white">Approve</Button><Button variant="outline" className="h-9 rounded-lg border-[#eedcbd] px-3 text-xs text-[#9d7546]">Decline</Button></div></div>)}</div> : <div className="mt-5 rounded-2xl border border-dashed border-[#ecd8b7] p-5 text-center text-sm text-[#a28662]">Run the monthly scan to create an approval request. Every escalation expires after 48 hours.</div>}</CardContent></Card>; }

function Services() { const guide = trpc.commute.guide.useMutation({ onSuccess: result => toast.success(`${result.city} guidance ready`), onError: error => toast.error(error.message) }); const [city, setCity] = useState("Chicago"); const [guideResult, setGuideResult] = useState<any>(null); useEffect(() => { if (guide.data) setGuideResult(guide.data); }, [guide.data]); const serviceCards = [{ icon: <Plane className="h-5 w-5" />, title: "Flights", detail: "Search and keep itinerary context", tone: "purple" as const }, { icon: <TrainFront className="h-5 w-5" />, title: "Trains", detail: "Schedules and station handoff", tone: "blue" as const }, { icon: <Bike className="h-5 w-5" />, title: "Bike-share", detail: "Nearby pickup guidance", tone: "green" as const }, { icon: <CarIcon />, title: "Rideshare", detail: "A clean handoff to your provider", tone: "orange" as const }]; return <div><AppTopbar title="Services" subtitle="Travel context and commute guidance, without pretending to sell tickets." onYuna={() => toast("Ask Yuna about your next stop after signing in.")} /><div className="mx-auto max-w-[1440px] space-y-8 px-5 py-7 sm:px-8 lg:px-10"><div><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-[#789086]">Services hub</p><h2 className="mt-2 font-display text-3xl font-semibold tracking-[-0.04em] text-[#18342e]">Get there, with less context switching.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#789086]">The commute agent provides guidance only. It reuses the same contactless capability shown in Payments — no separate transit rail and no ticket purchase flow.</p></div><Card className="overflow-hidden rounded-[1.75rem] border-0 bg-[#18342e] text-white shadow-[0_22px_60px_rgba(24,52,46,.16)]"><CardContent className="relative grid gap-8 p-6 sm:p-8 lg:grid-cols-[.9fr_1.1fr]"><div className="absolute -right-20 -top-36 h-80 w-80 rounded-full border-[48px] border-[#3a6a58]/35" /><div className="relative"><div className="flex items-center gap-2"><AgentBadge label="Commute Agent" tone="green" /><span className="rounded-full border border-[#426d5b] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.13em] text-[#acd6bd]">Mock geolocation</span></div><h3 className="mt-5 max-w-md font-display text-3xl font-semibold leading-tight tracking-[-0.04em]">You are somewhere new.<br /><span className="text-[#9ae7b5]">Keep tapping what you know.</span></h3><p className="mt-3 max-w-md text-sm leading-6 text-[#b4d1c2]">Pick a city from the demo reference set and the agent will identify the local open-loop transit system.</p><div className="mt-6 flex max-w-md gap-2"><Input value={city} onChange={event => setCity(event.target.value)} className="h-11 border-[#416b5b] bg-[#264c40] text-white placeholder:text-[#88a999]" placeholder="Chicago" /><Button onClick={() => guide.mutate({ city })} className="h-11 shrink-0 bg-[#a5e7b5] text-[#18342e] hover:bg-[#c1f1cc]">Guide me</Button></div><p className="mt-3 text-xs text-[#82a998]">Try Chicago, New York, San Francisco, or Washington DC.</p></div><div className="relative flex items-center"><div className="w-full rounded-[1.5rem] border border-[#416b5b] bg-[#21483c]/80 p-5"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-[#356453] text-[#a8e6b9]"><MapPin className="h-5 w-5" /></div><div><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#89b19d]">Detected city</p><p className="mt-1 font-display text-2xl font-semibold text-white">{guideResult?.city || "Chicago"}</p></div></div><BadgeCheck className="h-6 w-6 text-[#a1e3b2]" /></div><Separator className="my-5 bg-[#416b5b]" /><p className="text-sm leading-6 text-[#b8d7c7]">{guideResult?.copy || "CTA accepts contactless tap at supported rail stations and buses. Just tap your existing Momentum card at the reader — no separate ticket flow needed."}</p><div className="mt-5 flex items-center justify-between rounded-xl bg-[#315c4e] px-3 py-2.5"><span className="text-xs text-[#aad0bd]">Reference system</span><span className="text-sm font-semibold text-[#d8f3df]">{guideResult?.system || "CTA"} · contactless</span></div></div></div></CardContent></Card><div><SectionHeading eyebrow="Travel context" title="Your everyday shortcuts" detail="Open these surfaces for structure; provider connections are intentionally not built." /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{serviceCards.map(card => <button key={card.title} onClick={() => toast(`${card.title} guidance is a demo surface — no provider connection is wired.`)} className="flex items-center gap-4 rounded-2xl border border-[#e5eee8] bg-white p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><IconBubble tone={card.tone}>{card.icon}</IconBubble><span><span className="block text-sm font-semibold text-[#36574a]">{card.title}</span><span className="mt-1 block text-xs text-[#81948b]">{card.detail}</span></span></button>)}</div></div></div></div>; }
function CarIcon() { return <CreditCard className="h-5 w-5" />; }

function ActivityPage() { const data = usePlatformData(); return <div><AppTopbar title="Activity & explainability" subtitle="See what happened, what was notified, and why an agent made a decision." onYuna={() => toast("Ask Yuna after signing in to parse a command.")} /><div className="mx-auto max-w-[1440px] space-y-8 px-5 py-7 sm:px-8 lg:px-10"><div><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-[#789086]">Trust layer</p><h2 className="mt-2 font-display text-3xl font-semibold tracking-[-0.04em] text-[#18342e]">Nothing happens in the dark.</h2></div><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><Card className="rounded-[1.75rem] border-[#e5eee8] bg-white shadow-sm"><CardHeader className="px-6 pb-2 pt-6"><div className="flex items-center justify-between"><div><CardTitle className="font-display text-xl text-[#24463b]">Audit trail</CardTitle><p className="mt-1 text-sm text-[#789086]">Agent actions include the reasoning behind the result.</p></div><SimulatedBadge>30-day view</SimulatedBadge></div></CardHeader><CardContent className="px-6 pb-6"><div className="relative mt-4 space-y-1 before:absolute before:bottom-4 before:left-5 before:top-4 before:w-px before:bg-[#dcebe0]">{data.audit.map((item: any) => <AuditRow key={item.id} item={item} />)}</div></CardContent></Card><Card className="rounded-[1.75rem] border-[#e5eee8] bg-[#fbfdfb] shadow-sm"><CardHeader className="px-6 pb-2 pt-6"><CardTitle className="font-display text-xl text-[#24463b]">Notification center</CardTitle><p className="mt-1 text-sm text-[#789086]">Every agent decision fans out across four channels.</p></CardHeader><CardContent className="px-6 pb-6">{data.notifications.length ? data.notifications.slice(0, 8).map((item: any) => <div key={item.id} className="flex items-start gap-3 border-b border-[#edf3ee] py-3.5 last:border-0"><div className="grid h-8 w-8 place-items-center rounded-xl bg-[#eaf7ed] text-[#4e9867]">{item.channel === "sms" ? <Phone className="h-3.5 w-3.5" /> : item.channel === "email" ? <Send className="h-3.5 w-3.5" /> : item.channel === "push" ? <Bell className="h-3.5 w-3.5" /> : <Activity className="h-3.5 w-3.5" />}</div><div><p className="text-sm font-semibold text-[#36574a]">{item.title}</p><p className="mt-1 text-xs leading-5 text-[#81948b]">{item.body}</p><p className="mt-1 text-[10px] font-semibold uppercase tracking-wider text-[#a3b3a9]">{item.channel === "sms" ? "Simulated SMS" : item.channel.replace("_", " ")} · {item.status}</p></div></div>) : <EmptyState title="No new notifications" detail="New payment and agent decisions will appear here." />}</CardContent></Card></div></div></div>; }
function AuditRow({ item }: { item: any }) { const tone = item.agent === "bill_advisor" ? "purple" : item.agent === "commute" ? "orange" : "green"; return <div className="relative flex gap-4 rounded-2xl p-3 transition hover:bg-[#f8fbf8]"><div className="relative z-10 grid h-10 w-10 shrink-0 place-items-center rounded-2xl border-4 border-white bg-[#e1f4e6] text-[#4b9764]"><Sparkles className="h-4 w-4" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-[#36574a]">{item.action}</p><AgentBadge label={item.agent === "bill_advisor" ? "Bill Advisor" : item.agent === "commute" ? "Commute" : "System"} tone={tone as any} /></div><p className="mt-2 text-sm leading-6 text-[#789086]">{item.reasoning}</p><p className="mt-2 text-[10px] font-semibold uppercase tracking-wider text-[#a1b1a7]">{item.decision} · {new Date(item.createdAt).toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })}</p></div></div>; }

function Controls() { const data = usePlatformData(); const [autoSwitch, setAutoSwitch] = useState(Boolean(data.controls.autoSwitchEnabled)); const [maxSavings, setMaxSavings] = useState(String(Math.round(data.controls.maxMonthlySavingsCents / 100) || 0)); const [maxIncrease, setMaxIncrease] = useState(String(Math.round(data.controls.maxPriceIncreaseCents / 100) || 0)); const [sms, setSms] = useState(Boolean(data.controls.notifySms)); const [push, setPush] = useState(Boolean(data.controls.notifyPush)); const [email, setEmail] = useState(Boolean(data.controls.notifyEmail)); const update = trpc.controls.update.useMutation({ onSuccess: () => { toast.success("AI Controls saved"); data.refresh(); }, onError: error => toast.error(error.message) }); useEffect(() => { setAutoSwitch(Boolean(data.controls.autoSwitchEnabled)); setMaxSavings(String(Math.round(data.controls.maxMonthlySavingsCents / 100) || 0)); setMaxIncrease(String(Math.round(data.controls.maxPriceIncreaseCents / 100) || 0)); }, [data.controls]); return <div><AppTopbar title="AI Controls" subtitle="Your thresholds decide whether agents can act or must ask." onYuna={() => toast("Yuna can explain these controls after sign-in.")} /><div className="mx-auto max-w-[1100px] space-y-8 px-5 py-7 sm:px-8 lg:px-10"><div><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-[#789086]">Guardrails</p><h2 className="mt-2 font-display text-3xl font-semibold tracking-[-0.04em] text-[#18342e]">You set the autonomy level.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#789086]">First-run behavior is always ask. If you enable auto-switching, Bill Advisor can act only inside the exact thresholds you set here.</p></div><Card className="rounded-[1.75rem] border-[#e5eee8] bg-white shadow-sm"><CardContent className="p-6 sm:p-8"><div className="flex flex-col justify-between gap-5 border-b border-[#edf3ee] pb-6 sm:flex-row sm:items-center"><div className="flex items-start gap-4"><IconBubble tone={autoSwitch ? "green" : "orange"}>{autoSwitch ? <Zap className="h-5 w-5" /> : <Pause className="h-5 w-5" />}</IconBubble><div><h3 className="font-display text-xl font-semibold text-[#24463b]">Allow automatic plan switching</h3><p className="mt-1 max-w-xl text-sm leading-6 text-[#789086]">When off, every recommendation becomes an escalation. When on, the agent still cannot exceed the thresholds below.</p></div></div><Switch checked={autoSwitch} onCheckedChange={setAutoSwitch} /></div><div className="grid gap-5 py-7 sm:grid-cols-2"><div><Label htmlFor="max-savings" className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Maximum monthly savings to act on</Label><div className="relative mt-2"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-[#789086]">$</span><Input id="max-savings" value={maxSavings} onChange={event => setMaxSavings(event.target.value)} className="h-12 rounded-xl border-[#dfece2] pl-8 shadow-none" /></div><p className="mt-2 text-xs text-[#92a49b]">Example: $25 means the agent can switch up to $25/month savings.</p></div><div><Label htmlFor="max-increase" className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Maximum price increase allowed</Label><div className="relative mt-2"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-[#789086]">$</span><Input id="max-increase" value={maxIncrease} onChange={event => setMaxIncrease(event.target.value)} className="h-12 rounded-xl border-[#dfece2] pl-8 shadow-none" /></div><p className="mt-2 text-xs text-[#92a49b]">Keep at $0 to prevent any recommendation that costs more.</p></div></div><Separator /><div className="py-7"><p className="text-xs font-semibold uppercase tracking-wider text-[#6f897d]">Notification fan-out</p><p className="mt-1 text-sm text-[#789086]">Every automatic action or escalation triggers all enabled channels.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><ControlToggle icon={<Bell className="h-4 w-4" />} label="Push" checked={push} onChange={setPush} /><ControlToggle icon={<Send className="h-4 w-4" />} label="Email" checked={email} onChange={setEmail} /><ControlToggle icon={<Phone className="h-4 w-4" />} label="SMS (simulated)" checked={sms} onChange={setSms} /></div></div><div className="flex flex-col justify-between gap-4 rounded-2xl bg-[#f7faf7] p-4 sm:flex-row sm:items-center"><div className="flex items-start gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#e4f3e8] text-[#4d9565]"><ShieldCheck className="h-4 w-4" /></div><div><p className="text-sm font-semibold text-[#36574a]">Always-on audit trail</p><p className="mt-1 text-xs text-[#81948b]">Reasoning is visible even when a recommendation is declined.</p></div></div><Button onClick={() => update.mutate({ autoSwitchEnabled: autoSwitch, maxMonthlySavingsCents: Math.round(Number(maxSavings || 0) * 100), maxPriceIncreaseCents: Math.round(Number(maxIncrease || 0) * 100), notifyPush: push, notifyEmail: email, notifySms: sms })} disabled={update.isPending} className="h-10 rounded-xl bg-[#18342e] text-white hover:bg-[#2b5749]">{update.isPending ? "Saving…" : "Save controls"}</Button></div></CardContent></Card><div className="grid gap-4 sm:grid-cols-3"><SmallTrustCard icon={<LockKeyhole className="h-4 w-4" />} title="PIN + biometric" detail="Every transaction records an auth event." /><SmallTrustCard icon={<Network className="h-4 w-4" />} title="Four channels" detail="Push, email, inbox, and simulated SMS." /><SmallTrustCard icon={<Clock3 className="h-4 w-4" />} title="48-hour expiry" detail="Unactioned escalations re-prompt, then expire." /></div></div></div>; }
function ControlToggle({ icon, label, checked, onChange }: { icon: React.ReactNode; label: string; checked: boolean; onChange: (value: boolean) => void }) { return <div className="flex items-center justify-between rounded-2xl border border-[#e5eee8] p-3"><div className="flex items-center gap-2 text-sm font-medium text-[#36574a]"><span className="text-[#589b6c]">{icon}</span>{label}</div><Switch checked={checked} onCheckedChange={onChange} /></div>; }
function SmallTrustCard({ icon, title, detail }: { icon: React.ReactNode; title: string; detail: string }) { return <div className="rounded-2xl border border-[#e5eee8] bg-white p-4 shadow-sm"><div className="grid h-8 w-8 place-items-center rounded-xl bg-[#e9f7ec] text-[#4b9666]">{icon}</div><p className="mt-3 text-sm font-semibold text-[#36574a]">{title}</p><p className="mt-1 text-xs leading-5 text-[#81948b]">{detail}</p></div>; }

function YunaPanel({ onClose }: { onClose: () => void }) { const { isAuthenticated } = useAuth(); const transcribe = trpc.voice.transcribe.useMutation({ onError: error => toast.error(error.message) }); const parse = trpc.voice.parseIntent.useMutation({ onError: error => toast.error(error.message) }); const send = trpc.payments.send.useMutation({ onSuccess: () => { toast.success("Yuna transfer settled in demo mode"); onClose(); }, onError: error => toast.error(error.message) }); const [recording, setRecording] = useState(false); const [transcript, setTranscript] = useState(""); const [intent, setIntent] = useState<any>(null); const recorder = useRef<MediaRecorder | null>(null); const chunks = useRef<Blob[]>([]); const [wakeReady, setWakeReady] = useState(true); useEffect(() => { const timer = window.setTimeout(() => setWakeReady(true), 250); return () => window.clearTimeout(timer); }, []); const startRecording = async () => { if (!isAuthenticated) { toast("Sign in to unlock real Yuna transcription and intent parsing."); return; } try { const stream = await navigator.mediaDevices.getUserMedia({ audio: true }); const media = new MediaRecorder(stream); chunks.current = []; recorder.current = media; media.ondataavailable = event => { if (event.data.size) chunks.current.push(event.data); }; media.onstop = () => { stream.getTracks().forEach(track => track.stop()); const blob = new Blob(chunks.current, { type: media.mimeType || "audio/webm" }); const reader = new FileReader(); reader.onloadend = () => { const encoded = String(reader.result).split(",")[1] || ""; transcribe.mutate({ audioBase64: encoded, mimeType: blob.type || "audio/webm" }, { onSuccess: result => { setTranscript(result.text); parse.mutate({ transcript: result.text }, { onSuccess: parsed => setIntent(parsed) }); } }); }; reader.readAsDataURL(blob); }; media.start(); setRecording(true); } catch { toast.error("Microphone access was not available. You can still review the Yuna flow in demo mode."); } }; const stopRecording = () => { recorder.current?.stop(); setRecording(false); }; const confirm = () => { if (!intent?.matchedContact || intent.action !== "send_money") return; send.mutate({ recipientName: intent.matchedContact.displayName, recipientHandle: intent.matchedContact.handle, amountCents: Number(intent.amountCents), note: intent.note, authMethod: "biometric" }); }; return <div className="fixed inset-0 z-[100] flex items-end justify-center bg-[#18342e]/25 p-3 backdrop-blur-sm sm:items-center"><div className="w-full max-w-xl rounded-[1.75rem] border border-white/70 bg-[#fbfefb] shadow-[0_30px_90px_rgba(24,52,46,.25)]"><div className="flex items-start justify-between border-b border-[#e7efe9] p-5 sm:p-6"><div><div className="flex items-center gap-2"><AgentBadge label="Yuna" /><span className="rounded-full border border-[#d9e6ff] bg-[#f3f7ff] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.13em] text-[#5b7fae]">Real STT + LLM</span></div><h2 className="mt-3 font-display text-2xl font-semibold tracking-[-0.035em] text-[#24463b]">Hey Yuna</h2><p className="mt-1 max-w-sm text-sm leading-5 text-[#789086]">Speak a command. I’ll transcribe it, parse intent, and read it back before anything executes.</p></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl text-[#7c9489] transition hover:bg-[#edf5ef] hover:text-[#36574a]"><X className="h-4 w-4" /></button></div><div className="space-y-5 p-5 sm:p-6"><div className="flex items-center gap-3 rounded-2xl border border-[#dcebf4] bg-[#f5fbff] p-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#deeffa] text-[#5a8ab2]"><AudioLines className="h-4 w-4" /></div><div className="flex-1"><p className="text-xs font-semibold text-[#496e8d]">Privacy-first trigger</p><p className="mt-1 text-xs leading-5 text-[#7390a4]">{wakeReady ? "Local wake-word listener is ready; network-backed audio starts only after explicit mic capture." : "Preparing local listener…"}</p></div><span className="h-2 w-2 rounded-full bg-[#71c589] shadow-[0_0_0_4px_rgba(113,197,137,.15)]" /></div><div className="flex flex-col items-center rounded-[1.5rem] border border-[#e5eee8] bg-white p-6 text-center"><button onClick={recording ? stopRecording : startRecording} className={`grid h-20 w-20 place-items-center rounded-full transition ${recording ? "bg-[#ffe7e4] text-[#c76358] shadow-[0_0_0_10px_rgba(244,177,169,.18)]" : "bg-[#dff6e6] text-[#3d9860] shadow-[0_0_0_10px_rgba(167,226,181,.15)] hover:scale-105"}`}>{recording ? <MicOff className="h-7 w-7" /> : <Mic className="h-7 w-7" />}</button><p className="mt-4 text-sm font-semibold text-[#36574a]">{recording ? "Listening… tap to stop" : "Tap to speak"}</p><p className="mt-1 text-xs text-[#8aa097]">Try “send Ali Rahman $100 for dinner”</p></div>{transcribe.isPending && <div className="rounded-2xl bg-[#f7faf7] p-4 text-sm text-[#698178]">Transcribing with Whisper…</div>}{transcript && <div className="rounded-2xl border border-[#e5eee8] bg-[#fbfdfb] p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-[#91a49a]">Transcript</p><p className="mt-2 text-sm leading-6 text-[#36574a]">“{transcript}”</p></div>}{parse.isPending && <div className="rounded-2xl bg-[#f6f2ff] p-4 text-sm text-[#7760ad]">Yuna is parsing the intent…</div>}{intent && <div className="rounded-2xl border border-[#cfe8d5] bg-[#f0fbf2] p-4"><div className="flex items-start gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#d9f3df] text-[#4b9b65]"><Sparkles className="h-4 w-4" /></div><div className="flex-1"><p className="text-[10px] font-bold uppercase tracking-wider text-[#55946b]">Readback</p><p className="mt-2 text-sm font-semibold leading-6 text-[#36574a]">{intent.confirmationText}</p>{intent.matchedContact && <p className="mt-1 text-xs text-[#81948b]">Matched {intent.matchedContact.displayName} · {intent.matchedContact.handle}</p>}</div></div>{intent.matchedContact && intent.action === "send_money" && <div className="mt-4 flex gap-2"><Button variant="outline" onClick={() => setIntent(null)} className="h-10 flex-1 rounded-xl border-[#cfe5d4]">Not now</Button><Button onClick={confirm} disabled={send.isPending} className="h-10 flex-1 rounded-xl bg-[#3d9a63] text-white hover:bg-[#328654]">{send.isPending ? "Authorizing…" : "Confirm with biometric"}<Fingerprint className="ml-2 h-4 w-4" /></Button></div>}</div>}{!isAuthenticated && <p className="text-center text-xs text-[#8aa097]">Preview mode: sign in to run the real Whisper + LLM path. The rest of the flow is shown here for product review.</p>}</div></div></div>; }

export default function Home() { const [location] = useLocation(); const [yunaOpen, setYunaOpen] = useState(false); const page = location === "/payments" ? <Payments /> : location === "/bills" ? <Bills /> : location === "/services" ? <Services /> : location === "/activity" ? <ActivityPage /> : location === "/controls" ? <Controls /> : <Overview openYuna={() => setYunaOpen(true)} />; return <>{page}{yunaOpen && <YunaPanel onClose={() => setYunaOpen(false)} />}</>; }
